invokeWithErrorHandlingFactory(handleError): (handler, context?, args?) => any

Creates a function factory with error handling capabilities

Parameters

handleError

Fn

Error handling function to process exceptions during execution

Returns

Returns a new function that can execute target functions with automatic error handling

(handler, context?, args?) => any

Example

const errorHandler = (error) => console.error(error);
const safeExecute = invokeWithErrorHandlingFactory(errorHandler);

// Execute regular function
safeExecute(() => { throw new Error('test') });

// Execute async function
safeExecute(async () => { throw new Error('async test') });

Async flow control: retry, timeout, polling and sleeping.

retry

Retry a (sync or async) function until it succeeds or retries are exhausted.

const data = await retry(() => fetchData(), {
  retries: 3,          // default: 3
  delay: 1000,         // base delay in ms
  backoff: 'exponential', // 'fixed' | 'linear' | 'exponential'
  jitter: true,
  onRetry: (err, attempt, delay) => console.warn(`attempt ${attempt} failed, next in ${delay}ms`),
})

withTimeout

Race a promise against a time budget. Rejects with TimeoutError when the budget is exceeded (the underlying work is not cancelled — pass an AbortSignal for that).

try {
  await withTimeout(fetchData(), 3000)
} catch (e) {
  if (e instanceof TimeoutError) console.error('too slow')
}

waitFor

Poll a predicate until it returns a truthy value, or time out.

await waitFor(() => document.querySelector('#ready'), { interval: 100, timeout: 5000 })

sleep

Promise-based delay.

await sleep(1000) // wait 1s

Demo

retry against a flaky function that always fails twice before succeeding:

export default function App() {
  const [log, setLog] = useState([])
  const [running, setRunning] = useState(false)

  const run = async () => {
    setLog([])
    setRunning(true)
    let calls = 0
    const flaky = () => {
      calls++
      if (calls <= 2) return Promise.reject(new Error(`fail #${calls}`))
      return Promise.resolve(`ok after ${calls} calls`)
    }
    try {
      const result = await retry(flaky, {
        retries: 3,
        delay: 300,
        backoff: 'fixed',
        jitter: false,
        onRetry: (err, attempt, delay) =>
          setLog((l) => [...l, `⚠️ ${err.message} → retry ${attempt} in ${delay}ms`]),
      })
      setLog((l) => [...l, `✅ ${result}`])
    } catch (e) {
      setLog((l) => [...l, `❌ ${e.message}`])
    } finally {
      setRunning(false)
    }
  }

  return (
    <div style={{ fontFamily: 'monospace' }}>
      <button disabled={running} onClick={run}>
        {running ? 'running...' : 'run retry()'}
      </button>
      {log.map((line, i) => (
        <div key={i}>{line}</div>
      ))}
    </div>
  )
}

withTimeout racing a slow task against a 1s budget:

export default function App() {
  const [result, setResult] = useState('')

  const run = async (taskMs) => {
    setResult('running...')
    try {
      await withTimeout(sleep(taskMs), 1000)
      setResult(`✅ task (${taskMs}ms) finished within the budget`)
    } catch (e) {
      if (e instanceof TimeoutError) setResult(`⏰ TimeoutError: task (${taskMs}ms) exceeded 1000ms`)
    }
  }

  return (
    <div style={{ fontFamily: 'monospace' }}>
      <button onClick={() => run(500)}>fast task (500ms)</button>{' '}
      <button onClick={() => run(2000)}>slow task (2000ms)</button>
      <p>{result}</p>
    </div>
  )
}

Higher-order functions that wrap your functions with extra behavior.

defineDebounceFn

Debounce: only the last call within delay runs.

const onInput = defineDebounceFn((v) => search(v), 300)

defineThrottleFn

Throttle: at most one call per delay window.

const onScroll = defineThrottleFn(() => update(), 200)

defineOnceFn

The wrapped function can only be executed once.

const init = defineOnceFn(() => setup())
init() // runs
init() // no-op, returns cached result

defineSinglePromiseFn

Concurrent calls share a single in-flight promise.

const loadUser = defineSinglePromiseFn(() => fetchUser())
await Promise.all([loadUser(), loadUser()]) // one request only

Demo

Click fast and compare raw vs debounced vs throttled call counts:

export default function App() {
  const [raw, setRaw] = useState(0)
  const [debounced, setDebounced] = useState(0)
  const [throttled, setThrottled] = useState(0)
  const [once, setOnce] = useState(0)

  const fns = useMemo(
    () => ({
      debounce: defineDebounceFn(() => setDebounced((n) => n + 1), 500),
      throttle: defineThrottleFn(() => setThrottled((n) => n + 1), 500),
      once: defineOnceFn(() => setOnce((n) => n + 1)),
    }),
    []
  )

  const click = () => {
    setRaw((n) => n + 1)
    fns.debounce()
    fns.throttle()
    fns.once()
  }

  return (
    <div style={{ fontFamily: 'monospace', lineHeight: 2 }}>
      <button onClick={click}>click me fast!</button>
      <div>raw clicks: <b>{raw}</b></div>
      <div>debounce(500ms) fired: <b>{debounced}</b></div>
      <div>throttle(500ms) fired: <b>{throttled}</b></div>
      <div>once fired: <b>{once}</b> (always ≤ 1)</div>
    </div>
  )
}

String helpers.

capitalize

Capitalize the first letter of a string.

capitalize('string') // 'String'

unCapitalize

Lowercase the first letter of a string.

unCapitalize('String') // 'string'

underlineToHump

Convert snake_case to camelCase.

underlineToHump('hello_world') // 'helloWorld'

mulSplit

Split a string repeatedly by multiple separators.

mulSplit('a,b;c', ',;') // ['a', 'b', 'c']

Demo

Type below and watch each helper react:

export default function App() {
  const [text, setText] = useState('hello_world,foo_bar')

  const row = (name, value) => (
    <div>
      <code>{name}</code> → <b>{value}</b>
    </div>
  )

  return (
    <div style={{ fontFamily: 'monospace', lineHeight: 2 }}>
      <input
        value={text}
        onChange={(e) => setText(e.target.value)}
        style={{ width: 280 }}
      />
      {row('capitalize', capitalize(text))}
      {row('unCapitalize', unCapitalize(text))}
      {row('underlineToHump', underlineToHump(text))}
      {row('mulSplit(,_)', JSON.stringify(mulSplit(text, ',_')))}
    </div>
  )
}

Query string and path helpers.

queryStringToObject

Parse a query string into an object.

queryStringToObject('a=1&b=hello') // { a: '1', b: 'hello' }
queryStringToObject('foo[0]=1&foo[1]=2') // { foo: ['1', '2'] }

The input should be a bare query string. When reading from location.search, strip the leading ? first: queryStringToObject(location.search.slice(1)).

objectToQueryString

Serialize an object into a query string.

objectToQueryString({ a: 1, b: 'hello' }) // 'a=1&b=hello'

basename

Extract the last portion of a path, optionally stripping a suffix.

basename('/foo/bar/baz.txt') // 'baz.txt'
basename('/foo/bar/baz.txt', '.txt') // 'baz'

convertParamsRouterToRegExp

Convert a route pattern with :params into a RegExp.

convertParamsRouterToRegExp('/user/:id') // /^\/user\/([^/]+)$/

Demo

Edit the query string / path and watch the conversions:

export default function App() {
  const [qs, setQs] = useState('page=1&size=20&sort=desc')
  const [path, setPath] = useState('/api/users/list.ts')

  let parsed = {}
  let roundTrip = ''
  try {
    parsed = queryStringToObject(qs)
    roundTrip = objectToQueryString(parsed)
  } catch {
    /* typing in progress */
  }

  return (
    <div style={{ fontFamily: 'monospace', lineHeight: 2 }}>
      <div>
        query: <input value={qs} onChange={(e) => setQs(e.target.value)} style={{ width: 260 }} />
      </div>
      <div>→ object: <b>{JSON.stringify(parsed)}</b></div>
      <div>→ back to string: <b>{roundTrip}</b></div>
      <hr />
      <div>
        path: <input value={path} onChange={(e) => setPath(e.target.value)} style={{ width: 260 }} />
      </div>
      <div>→ basename: <b>{basename(path)}</b></div>
      <div>→ basename(path, '.ts'): <b>{basename(path, '.ts')}</b></div>
    </div>
  )
}

Type & value validators. All of them are TypeScript type guards.

Function	Checks
isStr / isBool / isNumber	primitive types
isObject / isFn / isSymbol / isPromise	reference types
isNull / isUndef / isNil	null-ish values
isPrimitive / isFalsy / isEffectiveNumber	composite checks

isPromise(Promise.resolve()) // true
isNil(null) // true
isNil(0) // false

Demo

Pick a value and see every validator's verdict:

import {
  isStr, isBool, isNumber, isObject, isFn, isPromise, isNil, isFalsy,
} from '@cc-heart/utils'

const candidates = {
  '"hello"': 'hello',
  '42': 42,
  'true': true,
  '{}': {},
  '() => {}': () => {},
  'Promise.resolve()': Promise.resolve(),
  'null': null,
  '0': 0,
}

const validators = { isStr, isBool, isNumber, isObject, isFn, isPromise, isNil, isFalsy }

export default function App() {
  const [key, setKey] = useState('Promise.resolve()')
  const value = candidates[key]

  return (
    <div style={{ fontFamily: 'monospace' }}>
      {Object.keys(candidates).map((k) => (
        <label key={k} style={{ display: 'inline-block', marginRight: 10 }}>
          <input type="radio" checked={key === k} onChange={() => setKey(k)} /> {k}
        </label>
      ))}
      <table style={{ marginTop: 8 }}>
        <tbody>
          {Object.entries(validators).map(([name, fn]) => (
            <tr key={name}>
              <td>{name}</td>
              <td style={{ color: fn(value) ? '#42b883' : '#e05561' }}>
                {String(fn(value))}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

Composable best practices for the fetch-based Request client.

Principle: small instances + composition

Prefer small focused instances over one instance with all interceptors. Combine them with factory functions:

// ── Building blocks: interceptors are pure functions ──
const addAuth: RequestInterceptor = (config) => ({
  ...config,
  headers: { ...config.headers, Authorization: `Bearer ${getToken()}` }
})

const addLang: RequestInterceptor = (config) => ({
  ...config,
  headers: { ...config.headers, 'Accept-Language': 'zh-CN' }
})

const handleError = (err: unknown) => {
  toast.error(err)
  return err
}

// ── Compose: each instance handles one concern ──
const authApi = new Request('https://api.example.com')
authApi.useRequestInterceptor(addAuth)
authApi.useRequestInterceptor(addLang)
authApi.useErrorInterceptor(handleError)

const publicApi = new Request('https://open.api.com')

// ── Or use helper functions ──
function withInterceptors(
  req: Request,
  interceptors: RequestInterceptor[]
): Request {
  interceptors.forEach((i) => req.useRequestInterceptor(i))
  return req
}
function withBaseUrl(url: string): Request {
  return new Request(url)
}

const api = withInterceptors(withBaseUrl('https://api.example.com'), [
  addAuth,
  addLang,
])

Four calling styles

const api = new Request('https://api.example.com')

// Style 1: async/await (recommended)
try {
  const user = await api.get<User>('/users/1')
  setUser(user)
} catch (e) {
  if ((e as Error).name === 'AbortError') return  // user cancelled
  toast.error(e)
}

// Style 2: lifecycle callbacks (React setState friendly)
api.get('/users', {
  onSuccess: setUsers,
  onError: toast.error,
  onFinally: () => setLoading(false),
})

// Style 3: promise chaining
api.get<number>('/count')
  .then(n => n * 2)
  .then(setCount)
  .catch(toast.error)

// Style 4: mixed (await + callbacks, non-conflicting)
const data = await api.get('/users', { onFinally: () => setLoading(false) })

Entity — group by domain

// entities/user.ts
const api = new Request('/api')

export const UserApi = {
  list: (page: number) =>
    api.get<User[]>('/users', { page }),
  get: (id: number) =>
    api.get<User>(`/users/${id}`),
  create: (data: CreateUserDto) =>
    api.post<User>('/users', data, { onSuccess: () => toast.success('created') }),
}

// Usage
const users = await UserApi.list(1)

Cache & dedup — isolated per instance

const cachedApi = new Request('/api')
// cache and dedup are instance-level, different Request instances are isolated
const data1 = await cachedApi.get('/users', {}, { cache: { ttl: 5000 } })
const data2 = await cachedApi.get('/users', {}, { cache: { ttl: 5000 } }) // cache hit

const otherApi = new Request('/api') // isolated cache

Try it online

A live Request demo against the public JSONPlaceholder API:

const api = new Request('https://jsonplaceholder.typicode.com')

export default function App() {
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')

  const load = async (id) => {
    setLoading(true)
    setError('')
    try {
      setUser(await api.get(`/users/${id}`))
    } catch (e) {
      setError(String(e))
    } finally {
      setLoading(false)
    }
  }

  return (
    <div style={{ fontFamily: 'monospace' }}>
      <button onClick={() => load(1)}>GET /users/1</button>{' '}
      <button onClick={() => load(999)}>GET /users/999 (error)</button>
      {loading && <p>loading...</p>}
      {error && <p style={{ color: 'red' }}>{error}</p>}
      {user && !loading && (
        <pre>{JSON.stringify(user, null, 2)}</pre>
      )}
    </div>
  )
}

Supports SSE streaming requests, built on Fetch API with these advantages over native EventSource:

✅ Custom Headers support

✅ POST requests support

✅ All HTTP methods supported

Basic usage

const api = new Request('https://api.example.com')

// GET SSE
const handle = api.sse('/events', {
  onMessage(event) {
    console.log('Received:', event.data)
  },
  onOpen() {
    console.log('Connection opened')
  },
  onError(error) {
    console.error('Connection error:', error)
  },
  onClose() {
    console.log('Connection closed')
  }
})

// Cancel connection
handle.abort()

POST SSE (e.g., AI streaming chat)

const handle = api.sse('/chat/completions', {
  method: 'POST',
  data: {
    prompt: 'Hello',
    model: 'gpt-4'
  },
  onMessage(event) {
    // Parse JSON data
    try {
      const data = JSON.parse(event.data)
      console.log('AI reply:', data.content)
    } catch {
      console.log('Raw data:', event.data)
    }
  },
  onError(err) {
    console.error('Request failed:', err)
  }
})

With interceptors

const addAuth: RequestInterceptor = (config) => ({
  ...config,
  headers: {
    ...config.headers,
    Authorization: `Bearer ${getToken()}`
  }
})

const api = new Request('https://api.example.com')
api.useRequestInterceptor(addAuth)

// SSE requests automatically include interceptor headers
const handle = api.sse('/protected/events', {
  onMessage(event) {
    console.log(event.data)
  }
})

Type definitions

interface SSEMessageEvent {
  event?: string    // Event type
  data: string      // Message data
  id?: string       // Last event ID
  retry?: number    // Retry interval (ms)
}

interface SSECallbacks {
  onMessage?: (event: SSEMessageEvent) => void
  onOpen?: () => void
  onError?: (error: unknown) => void
  onClose?: () => void
}
